{
  "voter": "codex",
  "round": 16,
  "date_iso": "2026-07-09",
  "verdicts": {
    "Q1": {
      "choice": "C",
      "rationale": "GCs think in per-panel when checking crate math but estimators immediately convert to $/SF; exposing both units eliminates back-of-napkin recalcs and mirrors the successful v0 transparency that drove leads without adding forbidden cost breakdown detail."
    },
    "Q2": {
      "choice": "C",
      "rationale": "The pipeline failed when prices vanished entirely, so they need to be discoverable everywhere buyers land: a rebuilt /pricing anchor for SEO, reinforced on each SKU page for context, and a hero hook on the homepage to re-establish the old “from $74 delivered” promise immediately."
    },
    "Q3": {
      "choice": "A",
      "rationale": "Individual `Offer` nodes per variant with price, USD currency, MadeToOrder availability, and priceValidUntil satisfy search/AI ingestion requirements without overcomplicating with eligibleQuantity logic or muting visibility via AggregateOffer ranges."
    },
    "Q4": {
      "i": {
        "choice": "INCLUDE",
        "rationale": "Stating DDP duty-paid is the differentiator versus domestic distributors and keeps expectation aligned with the direct-import model."
      },
      "ii": {
        "choice": "INCLUDE",
        "rationale": "The 3–4 week lead is part of ADR-049; surfacing it next to every price prevents ‘in stock’ assumptions."
      },
      "iii": {
        "choice": "INCLUDE",
        "rationale": "Full-container qualification prevents small-order noise and keeps messaging honest about the FCL-only economics."
      },
      "iv": {
        "choice": "INCLUDE",
        "rationale": "The delivered radius (100 mi from port) is material to landed cost; disclosing the limitation avoids disputes and hidden adders."
      },
      "v": {
        "choice": "INCLUDE",
        "rationale": "With tariffs possibly expiring in two weeks, tying each number to its as-of date is the clearest way to signal volatility while staying transparent."
      }
    },
    "Q5": {
      "choice": "C",
      "rationale": "A generic “leading US brand” reference supports the value claim but needs to appear wherever price-sensitive users enter—homepage, pricing hub, and subfloor page—without violating SB-3’s no-name rule."
    },
    "Q6": {
      "choice": "A",
      "rationale": "Maintaining visual parity by swapping the numeric price slot for a ‘Request delivered price’ CTA keeps those SKUs from feeling deprioritized while acknowledging the lack of a current list number."
    },
    "Q7": {
      "choice": "C",
      "rationale": "Pairing inline “Get your delivered price” CTAs with a calculator-to-lead flow ensures buyers who need custom freight zones or mixed loads can hand off their details right after seeing the list number, maximizing capture."
    },
    "Q8": {
      "i": {
        "choice": "INCLUDE",
        "rationale": "llms.txt is already the lightweight canonical feed for AI crawlers; adding the prices there ensures parity with what humans see."
      },
      "ii": {
        "choice": "INCLUDE",
        "rationale": "llms-full.txt is the long-form context file used by higher-verbosity agents, so keeping prices consistent avoids hallucinated deltas."
      },
      "iii": {
        "choice": "INCLUDE",
        "rationale": "The `/api/llm-context` endpoint powers partner agents; feeding the same DDP numbers minimizes downstream misquotes."
      },
      "iv": {
        "choice": "INCLUDE",
        "rationale": "Structured data via JSON-LD is now a major AI ingestion source; given Q3’s Offer selection, excluding prices there would create schema vs. copy mismatches."
      }
    },
    "Q9": {
      "choice": "A",
      "rationale": "Setting `priceValidUntil` to the expected tariff expiration date plus a visible subject-to-change note gives crawlers and buyers an explicit boundary, reducing the risk of the old price being cached after a tariff rollback."
    },
    "Q10": {
      "free_response": "The dual-unit presentation (panel + SF) should use a tight typographic lockup so that the SF conversion doesn’t crowd the CTA column, and the homepage hero should pair the $74 hook with the Made-to-order caveat so buyers immediately link the benefit and tradeoff. Ensure the calculator clearly states that quote outputs include the 15% surcharge so expectations don’t misalign after 7/24.",
      "future_items": [
        "Secure July 2026 Plycem price sheets for the four quote-only SKUs so the grid stays complete.",
        "Schedule a formal pricing review workflow tied to Section 122 expiration (and future surcharges) so priceValidUntil doesn’t lapse silently.",
        "Add a per-SF bulk calculator that factors mixed-thickness pallets to reduce pre-sale engineering back-and-forth."
      ]
    }
  },
  "overall_recommendation": "SHIP",
  "highest_confidence_finding": "Publishing prices across /pricing, product pages, and the homepage hero is essential to restoring the inbound lead flow that dropped to zero when the numbers vanished.",
  "lowest_confidence_finding": "Including the ‘leading US brand’ reference on all three surfaces should help framing, but without data on current visitor sensitivity to that claim, its marginal impact is less certain."
}
